'use strict';

// 五类素材类型定义：稳定别名、官方媒体类型、数量限制。
// 图片/视频/音频独立单调编号；文本/文档作为唯一 file。

const KINDS = Object.freeze({
  IMAGE: 'image',
  VIDEO: 'video',
  AUDIO: 'audio',
  TEXT: 'text',
  DOCUMENT: 'document'
});

const TOKEN_LABELS = Object.freeze({
  [KINDS.IMAGE]: '图片',
  [KINDS.VIDEO]: '视频',
  [KINDS.AUDIO]: '音频',
  [KINDS.TEXT]: '文本',
  [KINDS.DOCUMENT]: '文件'
});

// 官方媒体类型映射：图片/视频/音频用编号前缀，文本/文档合并为 file。
const OFFICIAL = Object.freeze({
  [KINDS.IMAGE]: Object.freeze({ type: 'reference_image', prefix: 'Image' }),
  [KINDS.VIDEO]: Object.freeze({ type: 'reference_video', prefix: 'Video' }),
  [KINDS.AUDIO]: Object.freeze({ type: 'reference_audio', prefix: 'Audio' }),
  [KINDS.TEXT]: Object.freeze({ type: 'file', phrase: '所附文本内容' }),
  [KINDS.DOCUMENT]: Object.freeze({ type: 'file', phrase: '所附参考文件' })
});

const LIMITS = Object.freeze({
  [KINDS.IMAGE]: 10,
  [KINDS.VIDEO]: 5,
  [KINDS.AUDIO]: 5,
  [KINDS.TEXT]: 1,
  [KINDS.DOCUMENT]: 1,
  total: 20
});

const ALL_KINDS = Object.freeze(Object.values(KINDS));

function isKind(kind) {
  return ALL_KINDS.includes(kind);
}

module.exports = { KINDS, TOKEN_LABELS, OFFICIAL, LIMITS, ALL_KINDS, isKind };
